8	/// Reusable searchable single-select screen for profession, nationality, ethnicity.
9	/// Fetches options from API endpoint with a "Suggested" section.
10	class SearchableSingleSelectScreen extends ConsumerStatefulWidget {
11	  const SearchableSingleSelectScreen({
12	    super.key,
13	    required this.title,
14	    required this.apiPath,
15	    required this.onConfirm,
16	    this.suggestedApiPath,
17	    this.initialValue,
18	    this.itemLabel,
19	    this.itemIcon,
20	    this.isSkippable = false,
21	    this.onSkip,
22	    this.currentStep = 0,
23	    this.totalSteps = 14,
24	    this.helpText,
25	  });
26	
27	  final String title;
28	  final String apiPath; // e.g. '/professions'
29	  final String? suggestedApiPath; // e.g. '/professions/suggested'
30	  final void Function(dynamic selected) onConfirm;
31	  final dynamic initialValue;
32	  final String Function(dynamic item)? itemLabel;
33	  final Widget Function(dynamic item)? itemIcon;
34	  final bool isSkippable;
35	  final VoidCallback? onSkip;
36	  final int currentStep;
37	  final int totalSteps;
38	  final String? helpText;
39	
40	  @override
41	  ConsumerState<SearchableSingleSelectScreen> createState() => _SearchableSingleSelectScreenState();
42	}
43	
44	class _SearchableSingleSelectScreenState extends ConsumerState<SearchableSingleSelectScreen> {
45	  final _searchCtrl = TextEditingController();
46	  List<dynamic> _allItems = [];
47	  List<dynamic> _suggestedItems = [];
48	  List<dynamic> _filteredItems = [];
49	  dynamic _selected;
50	  bool _loading = true;
51	  String _query = '';
52	
53	  @override
54	  void initState() {
55	    super.initState();
56	    _selected = widget.initialValue;
57	    _loadData();
58	    _searchCtrl.addListener(_onSearchChanged);
59	  }
60	
61	  @override
62	  void dispose() {
63	    _searchCtrl.removeListener(_onSearchChanged);
64	    _searchCtrl.dispose();
65	    super.dispose();
66	  }
67	
68	  Future<void> _loadData() async {
69	    setState(() => _loading = true);
70	    try {
71	      final api = ref.read(apiProvider);
72	      final all = await api.get<List<dynamic>>(widget.apiPath, (j) => (j as List).cast<dynamic>());
73	      _allItems = all;
74	      _filteredItems = all;
75	
76	      if (widget.suggestedApiPath != null) {
77	        final suggested = await api.get<List<dynamic>>(widget.suggestedApiPath!, (j) => (j as List).cast<dynamic>());
78	        _suggestedItems = suggested;
79	      }
80	    } catch (e) {
81	      if (mounted) {
82	        ScaffoldMessenger.of(context).showSnackBar(
83	          SnackBar(content: Text('Failed to load options: $e')),
84	        );
85	      }
86	    } finally {
87	      if (mounted) setState(() => _loading = false);
88	    }
89	  }
90	
91	  void _onSearchChanged() {
92	    final q = _searchCtrl.text.toLowerCase().trim();
93	    setState(() {
94	      _query = q;
95	      if (q.isEmpty) {
96	        _filteredItems = _allItems;
97	      } else {
98	        _filteredItems = _allItems.where((item) {
99	          final label = widget.itemLabel?.call(item) ?? item.toString();
100	          return label.toLowerCase().contains(q);
101	        }).toList();
102	      }
103	    });
104	  }
105	
106	  void _onItemTap(dynamic item) {
107	    setState(() => _selected = item);
108	  }
109	
110	  @override
111	  Widget build(BuildContext context) {
112	    final label = widget.itemLabel ?? ((item) => item['label']?.toString() ?? item['name']?.toString() ?? item.toString());
113	
114	    if (_loading) {
115	      return const Center(child: CircularProgressIndicator());
116	    }
117	
118	    return OnboardingScaffold(
119	      currentStep: widget.currentStep,
120	      totalSteps: widget.totalSteps,
121	      onBack: () => Navigator.of(context).pop(),
122	      onHelp: widget.helpText != null ? () => _showHelp(context) : null,
123	      bottomAction: Column(
124	        mainAxisSize: MainAxisSize.min,
125	        children: [
126	          FilledButton(
127	            onPressed: _selected != null ? () => widget.onConfirm(_selected!) : null,
128	            style: FilledButton.styleFrom(
129	              minimumSize: const Size.fromHeight(52),
130	              backgroundColor: Tokens.pink,
131	              shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(Tokens.radiusMd)),
132	            ),
133	            child: Text('Confirm (${_selected != null ? 1 : 0})', style: const TextStyle(fontWeight: FontWeight.w700, fontSize: 15)),
134	          ),
135	          if (widget.isSkippable && widget.onSkip != null) ...[
136	            const SizedBox(height: Tokens.spaceSm),
137	            TextButton(onPressed: widget.onSkip, child: const Text('Skip', style: TextStyle(fontSize: 14, color: Tokens.pinkDeep))),
138	          ],
139	        ],
140	      ),
141	      child: Column(
142	        crossAxisAlignment: CrossAxisAlignment.start,
143	        children: [
144	          Text(widget.title, style: Theme.of(context).textTheme.headlineSmall?.copyWith(color: Tokens.pinkDeep, fontWeight: FontWeight.w800)),
145	          const SizedBox(height: Tokens.spaceLg),
146	          // Search field
147	          TextField(
148	            controller: _searchCtrl,
149	            autofocus: true,
150	            decoration: InputDecoration(
151	              hintText: 'Search...',
152	              hintStyle: TextStyle(color: Colors.brown.shade300),
153	              prefixIcon: const Icon(Icons.search, color: Tokens.pink),
154	              filled: true,
155	              fillColor: Tokens.tanCard,
156	              contentPadding: const EdgeInsets.symmetric(vertical: 12, horizontal: 16),
157	              border: OutlineInputBorder(borderRadius: BorderRadius.circular(Tokens.radiusMd), borderSide: BorderSide.none),
158	              enabledBorder: OutlineInputBorder(
159	                borderRadius: BorderRadius.circular(Tokens.radiusMd),
160	                borderSide: BorderSide(color: Tokens.pink.withValues(alpha: 0.25)),
161	              ),
162	              focusedBorder: OutlineInputBorder(
163	                borderRadius: BorderRadius.circular(Tokens.radiusMd),
164	                borderSide: const BorderSide(color: Tokens.pink, width: 2),
165	              ),
166	            ),
167	          ),
168	          const SizedBox(height: Tokens.spaceMd),
169	          // List
170	          Expanded(
171	            child: _filteredItems.isEmpty && _query.isNotEmpty
172	                ? Center(child: Text('No results', style: TextStyle(color: Colors.brown.shade400)))
173	                : ListView(
174	                    children: [
175	                      if (_suggestedItems.isNotEmpty) ...[
176	                        _SectionHeader('Suggested'),
177	                        for (final item in _suggestedItems)
178	                          _buildItemTile(item, label, isSuggested: true),
179	                        const Divider(height: Tokens.spaceLg),
180	                      ],
181	                      _SectionHeader('All'),
182	                      for (final item in _filteredItems)
183	                        _buildItemTile(item, label),
184	                    ],
185	                  ),
186	          ),
187	        ],
188	      ),
189	    );
190	  }
191	
192	  Widget _buildItemTile(dynamic item, String Function(dynamic) label, {bool isSuggested = false}) {
193	    final isSelected = _selected == item;
194	    final itemLabel = label(item);
195	    final icon = widget.itemIcon?.call(item);
196	
197	    return RadioListTile<dynamic>(
198	      value: item,
199	      groupValue: _selected,
200	      onChanged: (v) => _onItemTap(v!),
201	      title: Row(
