class _PhotoSlot {
  const _PhotoSlot({this.url, this.isRemote = false, this.file});
  final String? url;
  final bool isRemote;
  final File? file;

  const _PhotoSlot.empty() : url = null, isRemote = false, file = null;

  bool get hasImage => url != null || file != null;
}

class _PhotoTile extends StatelessWidget {
  const _PhotoTile({
    super.key,
    required this.slot,
    required this.index,
    required this.isPrimary,
    required this.onRemove,
    required this.onSetPrimary,
    required this.busy,
  });

  final _PhotoSlot slot;
  final int index;
  final bool isPrimary;
  final VoidCallback onRemove;
  final VoidCallback onSetPrimary;
  final bool busy;

  @override
  Widget build(BuildContext context) {
    final scheme = Theme.of(context).colorScheme;

    return Stack(
      fit: StackFit.expand,
      children: [
        ClipRRect(
          borderRadius: BorderRadius.circular(Tokens.radiusSm),
          child: slot.isRemote
              ? Image.network(
                  slot.url!,
                  fit: BoxFit.cover,
                  width: double.infinity,
                  height: double.infinity,
                  loadingBuilder: (context, child, progress) => progress == null
                      ? child
                      : Center(
                          child: CircularProgressIndicator(
                            strokeWidth: 2,
                            value: progress.expectedTotalBytes != null ? progress.cumulativeBytesLoaded / progress.expectedTotalBytes! : null,
                            color: Tokens.pink,
                          ),
                        ),
                  errorBuilder: (_, __, ___) => Container(
                    color: scheme.surfaceContainerHighest,
                    child: const Icon(Icons.broken_image_outlined, color: Colors.grey),
                  ),
                )
              : Image.file(
                  slot.file!,
                  fit: BoxFit.cover,
                  width: double.infinity,
                  height: double.infinity,
                ),
        ),
        if (isPrimary)
          Positioned(
            left: 4,
            top: 4,
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 2),
              decoration: BoxDecoration(
                color: Tokens.pink,
                borderRadius: BorderRadius.circular(Tokens.radiusSm),
              ),
              child: const Text('Main', style: TextStyle(fontSize: 10, color: Colors.white, fontWeight: FontWeight.w700)),
            ),
          ),
        Positioned(
          right: 4,
          top: 4,
          child: Row(
            children: [
              if (!isPrimary)
                _CircleButton(
