  final String label;
  final IconData? icon;

  factory TagItem.fromJson(Map<String, dynamic> j) => TagItem(
        id: j['id'],
        label: j['label'] as String,
        icon: j['icon'] != null ? IconData(j['icon'] as int, fontFamily: 'MaterialIcons', matchTextDirection: true) : null,
      );
}

